1	import React from 'react';
2	import { chakra, useStyleConfig } from '@chakra-ui/react';
3	import { Link as RouterLink } from 'react-router-dom';
4	import { isSafeHref, isInternalHref } from 'app/utils/safeHref';
5	import { useSafeHref } from 'app/hooks/useSafeHref';
6	
7	type ZimmLinkBaseProps = {
8	  label: string;
9	  size?: 'large' | 'small';
10	};
11	
12	type ZimmAnchorLinkProps = ZimmLinkBaseProps & {
13	  href: string;
14	  onClick?: () => void;
15	};
16	
17	type ZimmButtonLinkProps = ZimmLinkBaseProps & {
18	  href?: never;
19	  onClick: () => void;
20	};
21	
22	/** Props union — href makes it an anchor; omitting href requires onClick (button semantics). */
23	export type ZimmLinkProps = ZimmAnchorLinkProps | ZimmButtonLinkProps;
24	
25	const ChakraRouterLink = chakra(RouterLink);
26	
27	/**
28	 * Atom — underlined text link rendered in two sizes (Large/Small).
29	 * Renders as `<button>` when no `href` is given. Otherwise: an internal href (see
30	 * `isInternalHref`) renders as a client-side-routed `<Link>`, prefixed with the current
31	 * site/locale via `useSafeHref()`; anything else `isSafeHref` allows (external/tel/mailto/#)
32	 * renders as a plain `<a>`, unprefixed — see `zimmNavItem/index.tsx`'s own fix for the same
33	 * class of bug (an unprefixed internal href always falls back to the default site).
34	 * All visual states live in `zimmLink.css.ts`.
35	 */
36	export const ZimmLink = (props: ZimmLinkProps) => {
37	  const { label, size = 'large', onClick } = props;
38	  const styles = useStyleConfig('ZimmLink', { size: size === 'small' ? 'sm' : 'lg' });
39	  const buildHref = useSafeHref();
40	
41	  if ('href' in props && props.href && isSafeHref(props.href)) {
42	    const { href } = props;
43	
44	    if (isInternalHref(href)) {
45	      return (
46	        <ChakraRouterLink to={buildHref(href)} onClick={onClick} __css={styles}>
47	          {label}
48	        </ChakraRouterLink>
49	      );
50	    }
51	
52	    return (
53	      <chakra.a href={href} onClick={onClick} __css={styles}>
54	        {label}
55	      </chakra.a>
56	    );
57	  }
58	
59	  return (
60	    <chakra.button type="button" onClick={onClick} __css={styles}>
